57 struct find_node_by_name_predicate {
58     std::string mName;
59     find_node_by_name_predicate(const std::string &name) :
60             mName(name) {
61         // empty
62     }
63 
64     bool operator()(pugi::xml_node node) const {
65         return node.name() == mName;
66     }
67 };
