152 
158     static inline bool getUIntAttribute(XmlNode &xmlNode, const char *name, unsigned int &val);
159 
165     static inline bool getIntAttribute(XmlNode &xmlNode, const char *name, int &val);
166 
172     static inline bool getRealAttribute(XmlNode &xmlNode, const char *name, ai_real &val);
