232 template <class TNodeType>
233 inline TXmlParser<TNodeType>::TXmlParser() :
234         mDoc(nullptr),
235         mData() {
236     // empty
237 }
238 
239 template <class TNodeType>
240 inline TXmlParser<TNodeType>::~TXmlParser() {
241     clear();
242 }
243 
244 template <class TNodeType>
245 inline void TXmlParser<TNodeType>::clear() {
246     if (mData.empty()) {
247         if (mDoc) {
248             delete mDoc;
249         }
250         mDoc = nullptr;
251         return;
252     }
253 
254     mData.clear();
255     delete mDoc;
256     mDoc = nullptr;
257 }
258 
259 template <class TNodeType>
260 inline TNodeType *TXmlParser<TNodeType>::findNode(const std::string &name) {
261     if (name.empty()) {
262         return nullptr;
263     }
264 
265     if (nullptr == mDoc) {
266         return nullptr;
267     }
268 
269     find_node_by_name_predicate predicate(name);
270     mCurrent = mDoc->find_node(predicate);
271     if (mCurrent.empty()) {
272         return nullptr;
273     }
274 
275     return &mCurrent;
276 }
277 
278 template <class TNodeType>
279 bool TXmlParser<TNodeType>::hasNode(const std::string &name) {
280     return nullptr != findNode(name);
281 }
282 
283 template <class TNodeType>
284 bool TXmlParser<TNodeType>::parse(IOStream *stream) {
285     if (hasRoot()) {
286         clear();
287     }
288 
289     if (nullptr == stream) {
290         ASSIMP_LOG_DEBUG("Stream is nullptr.");
291         return false;
292     }
293 
294     const size_t len = stream->FileSize();
295     mData.resize(len + 1);
296     memset(&mData[0], '\0', len + 1);
297     stream->Read(&mData[0], 1, len);
298 
299     mDoc = new pugi::xml_document();
300     pugi::xml_parse_result parse_result = mDoc->load_string(&mData[0], pugi::parse_full);
301     if (parse_result.status == pugi::status_ok) {
302         return true;
303     }
304 
305     ASSIMP_LOG_DEBUG("Error while parse xml.", std::string(parse_result.description()), " @ ", parse_result.offset);
306 
307     return false;
308 }
309 
310 template <class TNodeType>
311 bool TXmlParser<TNodeType>::hasRoot() const {
312     return nullptr != mDoc;
313 }
