345 template <class TNodeType>
346 inline bool TXmlParser<TNodeType>::hasAttribute(XmlNode &xmlNode, const char *name) {
347     pugi::xml_attribute attr = xmlNode.attribute(name);
348     return !attr.empty();
349 }
