480 using XmlParser = TXmlParser<pugi::xml_node>;
481 
483 class XmlNodeIterator {
484 public:
486     enum IterationMode {
487         PreOrderMode, 
488         PostOrderMode 
489     };
493     explicit XmlNodeIterator(XmlNode &parent, IterationMode mode) :
494             mParent(parent),
495             mNodes(),
496             mIndex(0) {
497         if (mode == PreOrderMode) {
498             collectChildrenPreOrder(parent);
499         } else {
500             collectChildrenPostOrder(parent);
501         }
502     }
503 
505     ~XmlNodeIterator() = default;
506 
509     void collectChildrenPreOrder(XmlNode &node) {
510         if (node != mParent && node.type() == pugi::node_element) {
511             mNodes.push_back(node);
512         }
513         for (XmlNode currentNode : node.children()) {
514             collectChildrenPreOrder(currentNode);
515         }
516     }
517 
520     void collectChildrenPostOrder(XmlNode &node) {
521         for (XmlNode currentNode = node.first_child(); currentNode; currentNode = currentNode.next_sibling()) {
522             collectChildrenPostOrder(currentNode);
523         }
524         if (node != mParent) {
525             mNodes.push_back(node);
526         }
527     }
528 
532     bool getNext(XmlNode &next) {
533         if (mIndex == mNodes.size()) {
534             return false;
535         }
536 
537         next = mNodes[mIndex];
538         ++mIndex;
539 
540         return true;
541     }
542 
545     size_t size() const {
546         return mNodes.size();
547     }
548 
551     bool isEmpty() const {
552         return mNodes.empty();
553     }
554 
556     void clear() {
557         if (mNodes.empty()) {
558             return;
559         }
560 
561         mNodes.clear();
562         mIndex = 0;
563     }
564 
565 private:
566     XmlNode &mParent;
567     std::vector<XmlNode> mNodes;
568     size_t mIndex;
569 };
